package shop.ultimatesmp.spawn;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class DuelTest {
 final UUID a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID();
 @Test void requestsNeedConsentAndDoNotEnableCombat(){DuelBook book=new DuelBook();assertTrue(book.request(a,b,100,1000));assertNull(book.match());assertFalse(DuelBook.combatAllowed(book.match(),a,b,101));assertNull(book.accept(b,c,101));assertNotNull(book.incoming(b,101));}
 @Test void selfRequestsAndConflictingRequestsAreRejected(){DuelBook book=new DuelBook();assertFalse(book.request(a,a,100,1000));assertTrue(book.request(a,b,100,1000));assertFalse(book.request(a,c,100,1000));assertFalse(book.request(c,b,100,1000));assertFalse(book.request(b,c,100,1000));}
 @Test void expiryIsInclusiveAndCannotBeAccepted(){DuelBook book=new DuelBook();book.request(a,b,100,30);assertNotNull(book.incoming(b,129));assertNull(book.accept(b,a,130));assertFalse(book.pending(a));}
 @Test void eitherParticipantCanCancelButStrangersCannot(){DuelBook book=new DuelBook();book.request(a,b,100,1000);assertNull(book.cancel(c));assertNotNull(book.cancel(b));assertNull(book.accept(b,a,101));assertTrue(book.request(a,c,102,1000));assertNotNull(book.cancel(a));assertFalse(book.pending(c));}
 @Test void onlyOneArenaMatchAndDuplicateAcceptCannotStartAnother(){DuelBook book=new DuelBook();book.request(a,b,100,1000);var match=book.accept(b,a,101);assertNotNull(match);assertEquals(b,match.opponent(a));assertThrows(IllegalArgumentException.class,()->match.opponent(c));assertNull(book.accept(b,a,102));assertFalse(book.request(c,a,102,1000));}
 @Test void preparingAndCountdownDoNotAllowDamageAndOutsidersNeverParticipate(){DuelBook book=new DuelBook();book.request(a,b,100,1000);book.accept(b,a,101);assertFalse(DuelBook.combatAllowed(book.match(),a,b,100000));var match=book.arm(200,3000,5000);assertFalse(DuelBook.combatAllowed(match,a,b,3199));assertTrue(DuelBook.combatAllowed(match,a,b,3200));assertTrue(DuelBook.combatAllowed(match,b,a,3200));assertFalse(DuelBook.combatAllowed(match,c,b,3200));assertFalse(DuelBook.combatAllowed(match,a,a,3200));assertFalse(DuelBook.combatAllowed(match,a,b,8200));assertNull(book.arm(300,10,10));}
 @Test void finishIsIdempotentAndAllowsLaterRequests(){DuelBook book=new DuelBook();book.request(a,b,100,1000);book.accept(b,a,101);assertNotNull(book.finish());assertNull(book.finish());assertTrue(book.request(c,b,102,1000));}
 @Test void returnMarkersSurviveRestartAndClearingOneDoesNotLoseTheOther(@TempDir Path dir)throws Exception{var store=new DuelReturnStore(dir.resolve("duel-returns.yml"));assertTrue(store.read().isEmpty());var vitals=new DuelVitals(18,17,4f,2f,0,123,List.of());store.save(Map.of(a,vitals,b,vitals));var recovered=new DuelReturnStore(dir.resolve("duel-returns.yml")).read();assertEquals(Map.of(a,vitals,b,vitals),recovered);recovered.remove(a);store.save(recovered);assertEquals(Set.of(b),store.read().keySet());String yaml=Files.readString(dir.resolve("duel-returns.yml"));assertFalse(yaml.contains("inventory"));assertFalse(yaml.contains("ender"));}
 @Test void invalidReturnFileIsNotSilentlyReset(@TempDir Path dir)throws Exception{Path file=dir.resolve("duel-returns.yml");String corrupt="version: 999\nplayers: {}\n";Files.writeString(file,corrupt);assertThrows(Exception.class,()->new DuelReturnStore(file).read());assertEquals(corrupt,Files.readString(file));}
 @Test void invalidVitalsCannotBePersisted(){assertThrows(IllegalArgumentException.class,()->new DuelVitals(Double.NaN,20,0,0,0,0,List.of()));assertThrows(IllegalArgumentException.class,()->new DuelVitals(20,100,0,0,0,0,List.of()));}
}
